# Generated by llm-saea. See adjacent provenance JSON.
from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.8, 'crossover': 0.9, 'exploration': 0.5, 'local_fraction': 0.2, 'radius': 0.2, 'population': 30, 'generations': 5, 'reason': 'With only 24 of 100 evaluations used and 19 stagnation steps with no recent improvement, more exploration is needed to escape the plateau. Raising exploration to 0.5 and radius to 0.2 favors novelty in the surrogate acquisition while keeping local exploitation moderate. A smaller population and 5 generations fit the remaining budget, and current_to_best with higher mutation/crossover balances surrogate-guided convergence with diversity. Auto surrogate selection adapts between RBF and quadratic given sparse 10D data.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
